module tb_TopModule;
  logic [7:0] a, b, c, d;
  logic [7:0] min;

  TopModule uut (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .min(min)
  );

  initial begin
    integer i, j, k, l;
    // Test random and corner cases
    a = 8'd50; b = 8'd20; c = 8'd100; d = 8'd10;
    #10;
    if (min !== 8'd10) begin
      $display("SELFTEST FAIL: expected 10, got %0d", min);
      $finish;
    end

    a = 8'd255; b = 8'd255; c = 8'd255; d = 8'd255;
    #10;
    if (min !== 8'd255) begin
      $display("SELFTEST FAIL: expected 255, got %0d", min);
      $finish;
    end

    a = 8'd0; b = 8'd1; c = 8'd2; d = 8'd3;
    #10;
    if (min !== 8'd0) begin
      $display("SELFTEST FAIL: expected 0, got %0d", min);
      $finish;
    end

    // Exhaustive or extensive randomized checks
    for (i = 0; i < 100; i = i + 1) begin
      a = $random;
      b = $random;
      c = $random;
      d = $random;
      #10;
      begin
        logic [7:0] expected;
        expected = a;
        if (b < expected) expected = b;
        if (c < expected) expected = c;
        if (d < expected) expected = d;
        if (min !== expected) begin
          $display("SELFTEST FAIL: a=%0d, b=%0d, c=%0d, d=%0d -> expected %0d, got %0d", a, b, c, d, expected, min);
          $finish;
        end
      end
    end

    $display("SELFTEST PASS");
    $finish;
  end
endmodule
